// Extract commits from GitHub push payload
const payload = $input.first().json.body ?? $input.first().json;

const ref = payload.ref ?? '';
const branch = ref.replace('refs/heads/', '');

// Only process pushes to main
if (branch !== 'main') {
  return [];
}

const repo = payload.repository?.full_name ?? 'unknown/repo';
const before = (payload.before ?? '').substring(0, 7);
const after = (payload.after ?? '').substring(0, 7);

const commits = (payload.commits ?? []).map(c => ({
  sha: c.id,
  message: c.message,
  author: c.author?.name ?? c.author?.username ?? 'unknown',
  url: c.url
}));

if (commits.length === 0) {
  return [];
}

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://fyrk-agent-runtime.fly.dev/run/release-notes',
  headers: { 'Content-Type': 'application/json' },
  body: {
    version: '0.1',
    input: {
      mode: 'fixture',
      repo,
      rangeLabel: `${before}..${after}`,
      commits
    },
    dryRun: false,
    publish: true
  },
  json: true,
  timeout: 30000
});

return [{ json: response }];

const data = $input.first().json;
const output = data.output;
const changes = output.changes;

// Skip if only chores (no user-facing changes)
if (changes.features.length === 0 && changes.fixes.length === 0) {
  return [];
}

// Build commit summary for Claude — include file paths for product attribution
const allCommits = [...changes.features, ...changes.fixes, ...changes.chores];
const allChanges = [];
for (const feat of changes.features) {
  allChanges.push(`[feature] ${feat.message.split('\n')[0]}`);
}
for (const fix of changes.fixes) {
  allChanges.push(`[fix] ${fix.message.split('\n')[0]}`);
}
for (const chore of changes.chores) {
  allChanges.push(`[chore] ${chore.message.split('\n')[0]}`);
}

// Extract changed file paths from webhook payload for product detection
const webhookData = $('Run Agent').first().json;
const pushPayload = $('GitHub Push Webhook').first().json.body ?? $('GitHub Push Webhook').first().json;
const changedPaths = (pushPayload.commits ?? []).flatMap(c => [...(c.added || []), ...(c.modified || []), ...(c.removed || [])]);
const uniquePaths = [...new Set(changedPaths)].slice(0, 30);

const date = output.date;
const executiveSummary = output.executiveSummary;
const highlights = output.highlights || [];

const systemPrompt = `Du er en copywriter for FYRK, et norsk fintech-selskap. Du skriver releaselog-entries for fyrk.no.

FYRK-plattformen bestar av flere produkter:
- **fyrk.no** — hovedsiden med informasjon om verktoy, tjenester, priser
- **Decision Loop** (loop.fyrk.no) — verktoy for beslutningsprosesser med innlogging (magic link). Kode i applications/decision-loop/

Nar endringer gjelder et spesifikt produkt (f.eks. Decision Loop), SKAL du navngi produktet i tittel og beskrivelse sa brukere forstar hva som er oppdatert. Bruk produktnavnet, ikke mappenavnet.

Regler:
- Skriv for sluttbrukere som bruker FYRK-plattformen, IKKE for utviklere
- Bruk norsk
- Abstraher tekniske detaljer til brukervendte beskrivelser
- Aldri nevn commit-hasher, filnavn, variabelnavn, eller tekniske implementasjonsdetaljer
- Grupper relaterte endringer under beskrivende overskrifter (### Heading)
- Bruk aktive verb: Lagt til, Rettet, Forbedret, Oppdatert, Fjernet
- Hopp over rene vedlikeholdsendringer (chores) med mindre de gir direkte brukerverdi
- Hvis ALLE endringer gjelder Decision Loop, prefix tittelen med "Decision Loop: "
- Hvis endringer gjelder bade fyrk.no og Decision Loop, grupper under separate overskrifter

Eksisterende stil (folg denne):
---
title: "Decision Loop: Forbedret sikkerhet for innlogging"
summary: "Rettet sikkerhetsproblem med magic link-autentisering i Decision Loop."

### Sikrere innlogging
Magic link-palogging i Decision Loop har fatt forbedret sikkerhetsvalidering.
---

Returner et JSON-objekt med noyaktig denne strukturen:
{
  "title": "Kort, beskrivende tittel (maks 60 tegn)",
  "summary": "En setning som oppsummerer endringene (maks 120 tegn)",
  "body": "Markdown-body med ### overskrifter og beskrivelser"
}

Returner KUN valid JSON, ingen annen tekst.`;

let userMessage = `Her er endringene som skal bli til en releaselog-entry:

Oppsummering: ${executiveSummary}

Endringer:
${allChanges.join('\n')}

Endrede filer:
${uniquePaths.join('\n')}`;

if (highlights.length > 0) {
  userMessage += `\n\nViktige punkter:\n${highlights.join('\n')}`;
}

userMessage += '\n\nSkriv en brukervendt releaselog-entry basert pa disse endringene.';

const requestBody = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 1024,
  messages: [
    {
      role: 'user',
      content: userMessage
    }
  ],
  system: systemPrompt
};

return [{
  json: {
    requestBody,
    date,
    changes
  }
}];

// Get Claude's response
const claudeResponse = $input.first().json;
const textContent = claudeResponse.content[0].text;

// Parse the JSON from Claude's response (strip markdown fences if present)
let jsonStr = textContent.trim();
if (jsonStr.startsWith('```')) {
  jsonStr = jsonStr.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
}
const parsed = JSON.parse(jsonStr);
const { title, summary, body } = parsed;

// Get date and changes from the Build Claude Request node
const date = $('Build Claude Request').first().json.date;
const changes = $('Build Claude Request').first().json.changes;

// Generate tags
const tags = [];
if (changes.features.length > 0) tags.push('feature');
if (changes.fixes.length > 0) tags.push('fix');
if (changes.chores.length > 0) tags.push('improvement');

// Sanitize for YAML frontmatter
const safeTitle = title.replace(/"/g, "'");
const safeSummary = summary.replace(/"/g, "'");

// Frontmatter
const frontmatter = `---\ntitle: "${safeTitle}"\ndate: ${date}\nsummary: "${safeSummary}"\ntags: ${JSON.stringify(tags)}\naudience: "user-facing"\ndraft: false\n---`;

const content = frontmatter + '\n\n' + body.trim() + '\n';

// Slug from title
const slug = title
  .toLowerCase()
  .replace(/[æ]/g, 'ae').replace(/[ø]/g, 'o').replace(/[å]/g, 'a')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '');

const filename = `${date}-${slug}.md`;
const path = `src/content/releaselog/${filename}`;

return [{
  json: {
    path,
    content,
    commitMessage: `docs: releaselog ${date}`,
    date
  }
}];

const data = $input.first().json;
const { path, content, commitMessage } = data;

const encoded = Buffer.from(content).toString('base64');

return [{
  json: {
    apiUrl: `https://api.github.com/repos/carlfrankalbert/nettside_fyrk/contents/${path}`,
    body: {
      message: commitMessage,
      content: encoded,
      committer: {
        name: 'FYRK Agent',
        email: 'agent@fyrk.no'
      }
    },
    path
  }
}];
